impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        let mut dp = vec![0; n];

        for i in (0..n).rev() {
            dp[i] = 0;
            for j in i + 1..n {
                dp[i] = dp[i].max(stone_value[i] + stone_value[j] - dp[j]);
            }
        }

        dp[0]
    }
}

